export interface GlowIconProps extends React.SVGProps<SVGSVGElement> {
  name: GlowIconName | string;
  size?: number | string;
  className?: string;
}

export default function GlowIcon({
  name,
  size = 18,
  className = "",
  ...props
}: GlowIconProps) {
  // Normalize alias mappings
  let resolvedName = name;
  if (name === "sparkles" || name === "star") resolvedName = "star";
  if (name === "building" || name === "building-2") resolvedName = "layers";
  if (name === "briefcase") resolvedName = "bag";
  if (name === "dollar-sign") resolvedName = "percent";
  if (name === "check-circle" || name === "check-circle-2") resolvedName = "checkmark-circle";
  if (name === "alert-circle") resolvedName = "alert-circle";
  if (name === "x") resolvedName = "xmark";
  if (name === "arrow-right") resolvedName = "arrow-right";
  if (name === "chevron-right") resolvedName = "chevron-right";
  if (name === "chevron-down") resolvedName = "chevron-down";
  if (name === "layout-grid") resolvedName = "grid";
  if (name === "table") resolvedName = "columns";
  if (name === "more-horizontal") resolvedName = "dots";
  if (name === "more-vertical") resolvedName = "more-vertical";
  if (name === "tag") resolvedName = "tag";
  if (name === "trending-up") resolvedName = "chart-up";
  if (name === "trash-2") resolvedName = "trash";
  if (name === "edit-3") resolvedName = "edit";
  if (name === "send") resolvedName = "paper-plane";
  if (name === "clock") resolvedName = "clock";
  if (name === "calendar") resolvedName = "calendar";
  if (name === "search") resolvedName = "search";
  if (name === "mail") resolvedName = "mail";
  if (name === "users") resolvedName = "users";
  if (name === "download") resolvedName = "download-cloud";
  if (name === "upload") resolvedName = "upload-cloud";
  if (name === "message-square") resolvedName = "message-square";
  if (name === "filter") resolvedName = "filter";
  if (name === "external-link") resolvedName = "external-link";
  if (name === "zap") resolvedName = "zap";
  if (name === "plus") resolvedName = "plus";

  const svgInner = GLOW_ICONS[resolvedName] || GLOW_ICONS["circle"] || "";

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      dangerouslySetInnerHTML={{ __html: svgInner }}
      {...props}
    />
  );
}
